import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int[] bowls = new int[n];
        for (int i = 0; i < n; i++) {
            bowls[i] = sc.nextInt();
        }

        for (int i = bowls.length - 1; i >= 0; i--) {
            System.out.println(bowls[i]);
        }
    }
}

