import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int[] bowls = new int[n];
        for (int i = 0; i < n; i++) {
            bowls[i] = sc.nextInt();
        }

        int count = 0;
        for (int x : bowls) {
            if (x >= 5) {
                count = count + 1;
            }
        }

        System.out.println("够 5 条的有 " + count + " 只碗喵");
    }
}

