import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int[][] grid = new int[2][2];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        int total = 0;
        for (int j = 0; j < 2; j++) {
            total = total + grid[1 - 1][j];
        }

        System.out.println("第 1 排一共 " + total + " 条喵");
    }
}

